#pragma once
#define BATTERIES_MOVABLE_HPP

#include <batteries/config.hpp>
//
#include <batteries/type_traits.hpp>
#include <batteries/utility.hpp>

#if BATT_CPP_20
#include <type_traits>
#endif  // BATT_CPP_20
#include <utility>

namespace batt {

template <typename T>
class Movable
{
   public:
    Movable() = default;

    template <typename... Args, typename = batt::EnableIfNoShadow<Movable, Args...>>
    explicit Movable(Args&&... args) noexcept : value_{BATT_FORWARD(args)...}
    {
    }

    Movable(const Movable&) = default;
    Movable& operator=(const Movable&) = default;

    Movable(Movable&& other) noexcept : value_{std::exchange(other.value_, T{})}
    {
    }

    Movable& operator=(Movable&& other) noexcept
    {
        if (this != &other) {
            this->value_ = std::exchange(other.value_, T{});
        }
        return *this;
    }

    operator T&()
    {
        return this->value_;
    }

    operator const T&() const
    {
        return this->value_;
    }

    T& ref() noexcept
    {
        return this->value_;
    }

    const T& cref() const noexcept
    {
        return this->value_;
    }

    template <typename U, typename = batt::EnableIfNoShadow<Movable, const U&>>
#if BATT_CPP_20
        requires(std::is_convertible_v<U, T>)
#endif  // BATT_CPP_20
    Movable& operator=(const U& new_value)
    {
        this->value_ = new_value;
        return *this;
    }

   private:
    T value_;
};

}  //namespace batt
